package com.lqq.supportflow.ticket.application;
import com.lqq.supportflow.ticket.domain.*; import java.util.List; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class ManageTicketService { private final TicketPort tickets; private final TicketCommentPort comments; public ManageTicketService(TicketPort tickets,TicketCommentPort comments){this.tickets=tickets;this.comments=comments;} public List<Ticket> list(Long tenantId){return tickets.list(tenantId);} @Transactional public Ticket claim(Long tenantId,Long ticketId,Long membershipId){return tickets.claim(tenantId,ticketId,membershipId);} @Transactional public Ticket changeStatus(Long tenantId,Long ticketId,TicketStatus status){return tickets.changeStatus(tenantId,ticketId,status);} @Transactional public TicketComment addComment(Long tenantId,Long ticketId,Long membershipId,String content){return comments.add(tenantId,ticketId,membershipId,content);} public List<TicketComment> comments(Long tenantId,Long ticketId){return comments.list(tenantId,ticketId);}}
